public List<String> getActiveCustomerNames(List<Customer> customers) {
    List<String> names = new ArrayList<>();
    for (Customer c : customers) {
        if (c.isActive() && c.getAge() >= 18) {
            names.add(c.getName().toUpperCase());
        }
    }
    return names;
}

